/* 青石县药农家庭：可搁置的沙盒往来；资料只读，行动才写入记录。 */
(()=>{'use strict';
const S=XTSandbox,W=XTWorld36,C=XTContent47,V=S.view;
const old={scene:renderScene,dispatch:S.dispatch,rooms:S.roomDefs,newGame,restore};
const labels={gather:'晒药坪与药样',sample:'药铺往来',sold:'家用与行装',done:'这回家事已交代'};
let message='';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state=()=>G?.family55||null,person=id=>G?.world36?.people?.[id];
const currentId=()=>G?.world36?.playerId;
function archived(){return !!state()&&state().ownerId!==currentId();}
function house(){const d=G?.homes41;return d?.places?.find(h=>h.id===(state()?.houseId||d.residenceId));}
function eligible(){return !!G?.root&&!!G.world36?.startGranted&&G.origin==='寒门散修'&&G.variantIdx===0&&G.birthContext?.id==='daliang-qing'&&!!house();}
function local(){return (G?.currentRegion48?.id||G?.birthContext?.id)==='daliang-qing';}
function mother(){const f=G?.family?.find(n=>n.sex==='女'&&['娘','母亲'].includes(n.name));return f?person('family_'+currentId()+'_'+f.id):null;}
function alive(n){return !!n&&n.alive!==false&&(!Number.isFinite(n.birth)||!Number.isFinite(n.life)||S.now()<n.birth+n.life*360);}
function homeHere(){const h=house();return local()&&h?.place===G.place&&['residence36','h41_inner'].includes(G.sandbox35?.room)&&h.residentIds.includes(currentId());}
function effectiveStage(){const q=state();return q?.stage==='sample'&&(G.inventory?.herb||0)<1?'gather':q?.stage;}
function record(q,text){q.journal.push({day:S.now(),text});q.journal=q.journal.slice(-24);addLog('家事 · '+text,'mute');}
function active(){const q=state();return !!q&&!archived()&&!q.paused;}
function transact(fn){const ok=C.atomic(fn);if(!ok)message=C.takeFailure()||'无法保存，本次家事行动已撤回。';render();return ok;}
function day(){const r=advanceDays(1,{act:'家事往来',rate:0,incomeMul:0},{stopOnEvent:true});if(r.died){die('寿元耗尽');return false;}if(r.event){startEvent(r.event);return false;}return r.days===1;}
function reconcile(){const q=state();if(!q||archived())return false;if(q.stage==='sample'&&(G.inventory?.herb||0)<1){q.stage='gather';q.sample=false;q.harvested=0;record(q,'带在行囊里的草药已作他用；愿意再走药路时，可以重新采备。');return true;}return false;}
function gathered(count,place){const q=state();if(active()&&local()&&q.stage==='gather'&&place==='village'&&S.state().room==='wild'&&Number.isSafeInteger(count)&&count>0){q.harvested+=count;record(q,'在乡中药坡实际采得青叶草'+count+'株；它们仍归你自由使用。');}}
function onTrade(id,key,selling,unit){const q=state();if(!active()||q.stage!=='sample'||!q.sample||key!=='herb'||!selling||id!==XTShop38.operator()||!local()||G.place!=='county'||!W.present(id))return;
 q.stage='sold';q.sample=false;q.proceeds=unit;q.buyerId=id;q.soldAt=S.now();record(q,'向在任药铺经办人'+person(id).name+'售出一份药样，实收'+unit+'灵石；没有另发家事赏钱。');}
function reason(type){const q=state();if(type==='begin'){if(q)return '这段往来已有记录，不必重演。';if(!eligible())return '这处家事只属于青石县药农家庭样板。';if(!homeHere())return '先回乡中旧居门厅或个人居室。';const kin=mother();if(alive(kin)&&!W.present(kin.id))return '母亲在旧居门厅，须当面说话。';return '';}
 if(!q||archived())return '这是上一代留存的家事记录，可阅读，不能重复结算。';if(['pause','resume'].includes(type))return '';if(q.paused)return '这段往来已搁置，可以随时继续。';const stage=effectiveStage();
 if(type==='dry'){if(stage!=='gather')return '这回药样已处理过。';if(!local()||G.place!=='village'||S.state().room!=='drying55')return '须到乡中晒药坪处理自己的药样。';if(q.harvested<1)return '先在乡中药坡实际采一回药；买来的材料不能代替辨药经历。';if((G.inventory.herb||0)<1)return '行囊里没有可处理的青叶草，可以先自由安排用途。';return '';}
 if(type==='sell'){if(stage!=='sample')return '眼下没有备妥的药样。';const id=XTShop38.operator();if(!local()||G.place!=='county'||!id||!W.present(id))return '须到县城商街，找到在任药铺经办人。';return '';}
 if(type==='support'||type==='keep'){if(stage!=='sold')return '本次尚无已经结清的药样货款。';if(!homeHere())return '这番打算留待回乡中旧居交代。';const kin=person(q.kinId);if(alive(kin)&&!W.present(kin.id))return '母亲在旧居门厅，须当面说明。';if(type==='support'){if(!kin)return '家人资料尚未核定，不能凭空指定收款人；可以整理记录并保留个人钱物。';if(!alive(kin))return '家人已故，不能继续向她交钱；可以整理记录，保留自己的行装钱。';if(G.stones<q.proceeds)return '货款已另作他用；愿意补作家用时先备齐，或说明自己的安排。';if(!Number.isSafeInteger((kin.family55Received||0)+q.proceeds))return '家庭收款记录超出可核算范围，暂不能交付；个人安排仍可照常说明。';}return '';}
 if(type==='visit'){if(stage!=='done'||q.visited)return '这回尚无新的回访可记录。';if(!(G.realm>q.closedRealm||G.realm===q.closedRealm&&G.layer>q.closedLayer))return '今后修行有了实际进展，愿意时再回来聊聊。';if(!homeHere())return '回访留待回到乡中旧居。';const kin=person(q.kinId);if(alive(kin)&&!W.present(kin.id))return '家人还在门厅，去见一面再说。';return '';}
 return '没有这项家事行动。';}
function dispatch(type){message='';if(type==='hide'){V.family55Hidden=true;render();return true;}if(!systemReady())return false;const why=reason(type);if(why){message=why;render();return false;}
 if(type==='pause'||type==='resume')return transact(()=>{const q=state();q.paused=type==='pause';record(q,q.paused?'暂且搁下家事，去做自己的事。':'又想起家里的药路，继续留意。');});
 if(type==='begin')return transact(()=>{if(!day())return;const kin=mother(),q=G.family55={version:1,ownerId:currentId(),houseId:house().id,kinId:kin?.id||null,stage:'gather',paused:false,harvested:0,sample:false,proceeds:0,choice:null,visited:false,journal:[]};record(q,alive(kin)?'与母亲核对旧账：父亲已故，箱底旧药款由家中保管。你可以自己走一回药路，也可以先去修行。':(kin?'整理旧居留存的药路记录；故人已去，不再有人等你交差。':'整理旧居留存的药路记录；家人资料尚未核定，不据缺失档案推定生死。'));});
 if(type==='dry')return transact(()=>{if(!day())return;if(reason('dry')){message='这次整理被打断，药样未记成。';return;}const q=state();q.stage='sample';q.sample=true;q.harvested--;record(q,'在晒药坪把一份自采青叶草拣净晾整，仍放在自己的行囊中；随时可以自用或出售。');});
 if(type==='sell'){V.tab='shop';V.detail={id:XTShop38.operator()};C.trade('herb',true);return state()?.stage==='sold';}
 if(type==='support'||type==='keep')return transact(()=>{if(!day())return;const why=reason(type);if(why){message=why;return;}const q=state(),kin=person(q.kinId);if(type==='support'){stoneChange(G,-q.proceeds,'把本次药样货款交作家用');kin.family55Received=(kin.family55Received||0)+q.proceeds;record(q,'把本次售药所得'+q.proceeds+'灵石交给'+kin.name+'作家用；箱底原有药款并未挪用。');}else record(q,alive(kin)?'把货款留下作自己的行装，也当面说清了打算。母亲说，走出去便照看好自己，不必把每一次回家都过成还债。':(kin?'把本次药款留作行装，在旧居记下自己的打算；故人不会再收到一笔虚构的钱。':'把药款留作自己的行装，记下家人资料待查；不虚构收款人与相见。'));q.choice=type;q.stage='done';q.closedRealm=G.realm;q.closedLayer=G.layer;q.closedAt=S.now();});
 if(type==='visit')return transact(()=>{if(!day())return;const q=state(),kin=person(q.kinId);q.visited=true;record(q,alive(kin)?(q.choice==='support'?'你又回来坐了一会儿。母亲记得那次家用，也问起你如今修行和谋生的打算。':'母亲仍记得你把药钱留作行装的那次交代。这回她先问起你一路见过的人。'):(kin?'修行又向前走了一步，你在旧居重读那段药路往来。屋里已无人应声，记录没有被重写成一次新的相见。':'你在旧居重读药路记录，家人资料仍待核定；没有把缺失档案写成一次重逢或死讯。'));});
 return false;}
function button(text,type,off=false){return '<button type="button" class="sb-btn" data-family55="'+type+'" '+(off?'disabled':'')+'>'+esc(text)+'</button>';}
function panel(){const q=state();if(!q&&!eligible())return '';if(!q){if(V.family55Hidden)return '';return '<section class="family55-card"><span class="family55-eyebrow">乡里 · 可自由参与</span><h3>家里的旧药路</h3><p>旧居里留着几笔药钱与往来。愿意时可回去听听；眼下修炼、谋生或远行，都不必先办完家事。</p>'+button('了解家中旧事 · 1日','begin',!!reason('begin'))+button('这次先不问','hide')+(message?'<p class="family55-notice" role="status">'+esc(message)+'</p>':'')+(reason('begin')?'<p class="family55-muted">'+esc(reason('begin'))+'</p>':'')+'</section>';}
 const stage=effectiveStage(),kin=person(q.kinId),history=q.journal.map(h=>'<p>'+esc(h.text)+'</p>').join('');let actions='',text='';
 if(archived())text='这段往来属于上一代。留下的记录可读，个人药样和货款沿原有继承规则处理，不再重演领取。';
 else if(q.paused){text='家事暂且搁下。你可以去任何已开放地点，照常修炼、谋生或结识旁人。';actions=button('继续留意这段往来','resume');}
 else if(stage==='gather'){text='愿意继续时，可在乡中药坡采药，到晒药坪拣净一份青叶草。现有自采记录 '+q.harvested+' 株；材料仍在行囊，任由你使用。';actions=button('拣净晾整药样 · 1日','dry',!!reason('dry'));}
 else if(stage==='sample'){text='一份药样仍在普通行囊中，可自用或出售。在县城与在任药铺经办人正常交易，也会记下本次货款。';actions=button('按药铺当前报价出售一份','sell',!!reason('sell'));}
 else if(stage==='sold'){text='本次已实收 '+q.proceeds+' 灵石。回旧居后，既可交作家用，也可把钱留作行装。'+(!kin?'家人资料尚未核定，暂不能交付家用。':!alive(kin)?'家人已经故去，只能整理记录，不能再向她交钱。':'');actions=button('把本次货款交作家用 · 1日','support',!!reason('support'))+button(alive(kin)?'留作行装，当面说明 · 1日':'留作行装，整理记录 · 1日','keep',!!reason('keep'));}
 else{text='这回家事已说清。你的选择是'+(q.choice==='support'?'交作家用':'留作行装')+'，没有善恶判定，也不影响你之后的修行。';if(!q.visited)actions=button('回访，说说近况 · 1日','visit',!!reason('visit'));}
 let blocked='';if(!archived()&&!q.paused){const next={gather:'dry',sample:'sell',sold:'keep',done:'visit'}[stage];if(next&&reason(next))blocked='<p class="family55-muted">'+esc(reason(next))+'</p>';}
 const receipt=G.places45?.chains?.[currentId()];return '<section class="family55-card"><header><span class="family55-eyebrow">青石县 · 药农家庭'+(archived()?' · 上一代记录':q.paused?' · 已搁置':'')+'</span><h3>'+esc(labels[stage]||'家中往来')+'</h3></header><p>'+esc(text)+'</p><div class="family55-actions">'+actions+'</div>'+blocked+(message?'<p class="family55-notice" role="status">'+esc(message)+'</p>':'')+(!archived()&&!q.paused&&q.stage!=='done'?'<div class="family55-pause">'+button('先去做别的事','pause')+'</div>':'')+'<details><summary>药路与乡里见闻（可选）</summary><p>'+(receipt?.stage==='done'?'你已办过当地药货回执，河埠、仓廪与客栈如何交接已有记录，不会再发一份报酬。':'县城来安客栈、河埠与仓廪也有独立的药货回执往来。有空可以另行了解，不是这段家事的前置条件。')+'</p></details><details><summary>家事记录 · '+q.journal.length+'则</summary>'+history+'</details></section>';}
function accepted(){const q=state();if(!q||archived()||q.paused||q.stage==='done')return [];const s=effectiveStage(),next={gather:['乡中药坡／晒药坪','自由采备青叶草，再到晒药坪拣净晾整一份。'],sample:['县城商街 · 在任药铺经办人','正常出售一份药样即可；药样也可以自用，另备后再来。'],sold:['乡中旧居门厅','回家说明药款打算，可交作家用或留下作行装。']}[s];return [{title:'家事：旧药路（可选）',status:'留意中',text:labels[s],where:next[0],next:next[1],need:'无强制期限，可随时搁置；不锁住修炼、旅行或公共支线。',finish:'家用和个人钱物分开记录；没有额外剧情赏钱。'}];}
function bind(root){root.querySelectorAll('[data-family55]').forEach(b=>b.onclick=()=>dispatch(b.dataset.family55));}
function decorate(){if(!G||G.mode!=='idle')return;const h=house(),room=G.sandbox35?.room,show=V.tab==='home'&&['','overview'].includes(V.sub||'')||V.tab==='scene'&&(room==='drying55'||local()&&h?.place===G.place&&['residence36','h41_inner'].includes(room))||V.tab==='shop'&&state()&&V.detail?.id===XTShop38.operator();if(!show)return;const scroll=document.getElementById('scene')?.querySelector('.sb-scroll');if(!scroll?.parentNode||scroll.querySelector('.family55-card'))return;if(room==='drying55'){const description=document.querySelector('.next-hero-copy p');if(description)description.textContent='竹匾在风里晾着，药叶与根须分开放。愿意时可整理自己的药样，旁人的药材不能取用。';}const html=panel();if(!html)return;const node=document.createElement('div');node.innerHTML=html;(scroll.querySelector('.next-main')||scroll).append(node);bind(node);}
const mapRooms=XTMap45.rooms;XTMap45.rooms=function(base){const rs=mapRooms(base);return local()&&G.place==='village'&&(eligible()||state())?[...rs,['drying55','乡中晒药坪']]:rs;};
S.dispatch=function(a,arg){if(a?.startsWith('f55:'))return dispatch(a.slice(4));const out=old.dispatch(a,arg);if(reconcile()){save();render();}return out;};
const oldAccepted=XTScene46.accepted;XTScene46.accepted=function(){return [...oldAccepted(),...accepted()];};
renderScene=function(...args){const out=old.scene(...args);decorate();return out;};
newGame=function(...args){const carry=args.length>=4&&G?.mode==='dead'&&state()?JSON.parse(JSON.stringify(state())):null;V.family55Hidden=false;message='';const out=old.newGame(...args);if(carry)G.family55=carry;return out;};
restore=function(raw){try{const incoming=JSON.parse(raw),q=incoming.family55;if(q!=null){if(typeof q!=='object'||Array.isArray(q)||q.version!==1||!['gather','sample','sold','done'].includes(q.stage)||typeof q.ownerId!=='string'||typeof q.houseId!=='string'||typeof q.paused!=='boolean'||typeof q.sample!=='boolean'||typeof q.visited!=='boolean'||!Number.isSafeInteger(q.harvested)||q.harvested<0||!Number.isSafeInteger(q.proceeds)||q.proceeds<0||!Array.isArray(q.journal)||q.journal.length>24||q.journal.some(h=>!Number.isSafeInteger(h.day)||typeof h.text!=='string')||q.kinId!==null&&typeof q.kinId!=='string'||!incoming.homes41?.places?.some(h=>h.id===q.houseId)||q.stage==='sample'&&!q.sample||['sold','done'].includes(q.stage)&&q.proceeds<1||q.stage==='done'&&(!['support','keep'].includes(q.choice)||!Number.isInteger(q.closedRealm)||!Number.isInteger(q.closedLayer)))throw Error('家事数据无效');}for(const n of Object.values(incoming.world36?.people||{}))if(n.family55Received!=null&&(!Number.isSafeInteger(n.family55Received)||n.family55Received<0))throw Error('家庭收款无效');}catch(e){XTEconomy40.lastRestoreError='家庭往来记录无效，当前存档保留。';return false;}message='';const ok=old.restore(raw);if(ok)reconcile();return ok;};
window.XTFamily55={state,eligible,archived,dispatch,panel,accepted,gathered,onTrade,reconcile,scope:{county:'daliang-qing',origin:'寒门散修',variant:0,room:'drying55'}};
})();
